from datetime import datetime, timezone
from uuid import uuid4
from fastapi import FastAPI
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict, StrictStr, field_validator
from starter.domain import normalize_title
app = FastAPI(title='My Taskboard')
tasks = {}
class CreateTask(BaseModel):
    model_config = ConfigDict(extra='forbid')
    title: StrictStr
    @field_validator('title')
    @classmethod
    def valid_title(cls, value):
        return normalize_title(value)
@app.get('/livez')
def livez():
    return {'status': 'ok'}
@app.post('/tasks', status_code=201)
def create(body: CreateTask):
    task_id = str(uuid4())
    task = {'id': task_id, 'title': body.title, 'completed': False,
            'created_at': datetime.now(timezone.utc).isoformat().replace('+00:00', 'Z'),
            'completed_at': None}
    tasks[task_id] = task
    return JSONResponse(task, status_code=201, headers={'Location': '/tasks/' + task_id})
@app.get('/tasks')
def list_tasks():
    return {'items': sorted(tasks.values(), key=lambda t: (t['created_at'], t['id']))}
PY
